#!/system/bin/sh
# ============================================================
#  Unicorn 1.34.2  -  dual-ABI self-extracting launcher
#  arm64-v8a (64-bit) + armeabi-v7a (32-bit) payloads inside.
#
#  Usage (adb shell / root shell / terminal):
#      sh unicorn_v1.34.2.sh
#      ./unicorn_v1.34.2.sh
#
#  The kernel decides which ELF class it can exec, so we probe
#  `uname -m` first (aarch64 = 64-bit kernel) and cross-check
#  with getprop. Wrong pick is auto-fallbacked by ELF-magic check.
# ============================================================

UC_VER="1.34.2"
UC_DIR="/data/local/A-LAB"
UC_BIN="$UC_DIR/.unicorn"
UC_APP="$UC_BIN/unicorn"

msg() { echo "[*] Unicorn v$UC_VER: $1"; }
fail() { echo "[!] Unicorn v$UC_VER: $1" >&2; exit 1; }

# ---------- 1. locate payload section inside this script ----
[ -f "$0" ] || fail "cannot read myself ($0)"
grep -q '^#__UC64_START__$' "$0" 2>/dev/null || fail "payload markers missing - file corrupted (re-download)"

# ---------- 2. decide 32 / 64 --------------------------------
USE64=0
KARCH="$(uname -m 2>/dev/null)"
GABI="$(getprop ro.product.cpu.abi 2>/dev/null)"
case "$KARCH" in
    aarch64) USE64=1 ;;
    armv7l|armv8l|armv6l|arm) USE64=0 ;;
    *)
        # uname unhelpful (e.g. x86 emulator) -> trust getprop abilist
        case "$GABI" in
            arm64-v8a) USE64=1 ;;
            armeabi*)  USE64=0 ;;
            *)
                # last resort: does the 64-bit linker exist?
                [ -x /system/bin/linker64 ] && USE64=1 || USE64=0
                ;;
        esac
        ;;
esac
# 64-bit kernel but ROM exposes no 64 ABI -> still fine to run 64.
# 32-bit kernel (armv7l/armv8l) on 64-bit CPU -> MUST run 32. (kernel = exec authority)

# ---------- 3. extract the right payload ---------------------
mkdir -p "$UC_BIN" 2>/dev/null || fail "cannot create $UC_BIN (need root?)"
B64="base64 -d"
command -v base64 >/dev/null 2>&1 || command -v toybox >/dev/null 2>&1 || B64="busybox base64 -d"

extract() { # $1=start-marker $2=end-marker $3=outfile
    sed -n "/^#$1\$/,/^#$2\$/p" "$0" | sed '1d;$d' | $B64 > "$3" 2>/dev/null
}

is_elf() { [ "$(head -c 4 "$1" 2>/dev/null | od -An -tx1 | tr -d ' \n')" = "7f454c46" ]; }

if [ "$USE64" = "1" ]; then
    msg "64-bit kernel detected ($KARCH) - extracting arm64 binary..."
    extract __UC64_START__ __UC32_START__ "$UC_APP.tmp" \
        || fail "arm64 payload decode failed"
    is_elf "$UC_APP.tmp" || fail "arm64 payload corrupt"
else
    msg "32-bit kernel detected ($KARCH) - extracting armv7 binary..."
    fail "32-bit payload not included in this build (64-bit only)" \
        || fail "armv7 payload decode failed"
    is_elf "$UC_APP.tmp" || fail "armv7 payload corrupt"
fi
mv -f "$UC_APP.tmp" "$UC_APP"
chmod 755 "$UC_APP" 2>/dev/null || fail "chmod failed - run as root: su -c 'sh $0'"

# ---------- 4. launch ----------------------------------------
msg "launching $UC_APP"
cd "$UC_BIN" 2>/dev/null || fail "cd $UC_BIN failed"
exec "$UC_APP" "$@"

